# TASK-20260928-d1ad97 / Q1 structural-fact check by exhaustive enumeration.
# For every finite abelian group G of order n <= NMAX (every isomorphism type), enumerate
# every set partition of G (as an onto map h to blocks), and test whether the induced
# combining rule f on blocks is well defined (exact sum-compatibility). Record:
#   (a) the set of block counts M for which a compatible partition exists,
#   (b) whether every compatible partition is the coset partition of a subgroup,
#   (c) whether the induced f is always invertible in each argument (a Latin square),
#   (d) the count of compatible partitions with M blocks versus the number of subgroups
#       of order n/M found by an independent subset enumeration.
# Expected under the claimed theorem: (a) equals the divisor set of n, (b),(c) always true,
# (d) equal counts. Pure Python; no library beyond itertools.
import itertools, sys, time
NMAX = 10

def factor(n):
    f = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f

def int_partitions(n, maxpart=None):
    if maxpart is None:
        maxpart = n
    if n == 0:
        yield []
        return
    for k in range(min(n, maxpart), 0, -1):
        for rest in int_partitions(n - k, k):
            yield [k] + rest

def abelian_groups_of_order(n):
    per_prime = []
    for p, e in sorted(factor(n).items()):
        per_prime.append([[p ** a for a in part] for part in int_partitions(e)])
    for combo in itertools.product(*per_prime):
        yield [m for grp in combo for m in grp]

def set_partitions(n):
    a = [0] * n
    def rec(i, m):
        if i == n:
            yield a[:], m
            return
        for v in range(m + 1):
            a[i] = v
            yield from rec(i + 1, m + (1 if v == m else 0))
    yield from rec(1, 1)

def divisors(n):
    return [d for d in range(1, n + 1) if n % d == 0]

grand_ok = True
for n in range(1, NMAX + 1):
    for mods in abelian_groups_of_order(n):
        elems = list(itertools.product(*[range(m) for m in mods]))
        idx = {e: i for i, e in enumerate(elems)}
        add = [[idx[tuple((x + y) % m for x, y, m in zip(elems[i], elems[j], mods))]
                for j in range(n)] for i in range(n)]
        neg = [idx[tuple((-x) % m for x, m in zip(elems[i], mods))] for i in range(n)]
        zero = idx[tuple(0 for _ in mods)]
        # independent subgroup count by subset enumeration
        sub_by_order = {}
        for mask in range(1, 1 << n):
            if not (mask >> zero) & 1:
                continue
            members = [i for i in range(n) if (mask >> i) & 1]
            if all((mask >> add[i][j]) & 1 for i in members for j in members):
                sub_by_order[len(members)] = sub_by_order.get(len(members), 0) + 1
        compat_by_M = {}
        all_coset = True
        all_latin = True
        t0 = time.time()
        for labels, M in set_partitions(n):
            f = [[-1] * M for _ in range(M)]
            ok = True
            for i in range(n):
                li = labels[i]
                row = f[li]
                addi = add[i]
                for j in range(n):
                    lj = labels[j]
                    s = labels[addi[j]]
                    if row[lj] == -1:
                        row[lj] = s
                    elif row[lj] != s:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue
            compat_by_M[M] = compat_by_M.get(M, 0) + 1
            latin = all(sorted(r) == list(range(M)) for r in f) and \
                    all(sorted(f[a][b] for a in range(M)) == list(range(M)) for b in range(M))
            all_latin &= latin
            H = [i for i in range(n) if labels[i] == labels[zero]]
            closed = all(labels[add[i][j]] == labels[zero] for i in H for j in H)
            cosets = all((labels[i] == labels[j]) == (labels[add[i][neg[j]]] == labels[zero])
                         for i in range(n) for j in range(n))
            all_coset &= (closed and cosets)
        Ms = sorted(compat_by_M)
        divs = divisors(n)
        counts_match = all(compat_by_M[M] == sub_by_order.get(n // M, 0) for M in Ms) and \
                       all(sub_by_order.get(n // d, 0) == compat_by_M.get(d, 0) for d in divs)
        ok_all = (Ms == divs) and all_coset and all_latin and counts_match
        grand_ok &= ok_all
        print("n=%2d G=Z/%s M-set=%s divisors=%s counts=%s subgroups(by order)=%s coset=%s latin=%s OK=%s (%.1fs)" % (
            n, "xZ/".join(map(str, mods)), Ms, divs,
            [compat_by_M[M] for M in Ms], dict(sorted(sub_by_order.items())),
            all_coset, all_latin, ok_all, time.time() - t0))
print("ALL GROUPS OF ORDER <= %d CONSISTENT WITH THE THEOREM:" % NMAX, grand_ok)
